// Step 1: Get project summary and mixins/relation groups in parallel
const [summary, schema] = await Promise.all([
  tools.graph_get_project_summary({}),
  tools.graph_get_mixins_and_relation_groups({})
]);

return { summary, schema };

// Search for transaction, payment, merchant, settlement-related nodes
const terms = ["transaction", "payment", "merchant", "settlement", "currency", "amount"];
const results = {};

for (const term of terms) {
  const res = await tools.graph_search_nodes({ expression: term, pageSize: 10 });
  results[term] = res;
}

return results;
